from typing import Any, Dict, Iterable, List, Optional, Union


class DataProcessor:
    def __init__(self, data: List[Dict[str, Any]]) -> None:
        self.data = data

    def filter(self, field: str, value: Any) -> List[Dict[str, Any]]:
        return [item for item in self.data if item.get(field) == value]

    def sort(self, key: str, reverse: bool = False) -> List[Dict[str, Any]]:
        return sorted(self.data, key=lambda x: x.get(key), reverse=reverse)

    def group(self, field: str) -> Dict[Any, List[Dict[str, Any]]]:
        groups: Dict[Any, List[Dict[str, Any]]] = {}
        for item in self.data:
            k = item.get(field)
            groups.setdefault(k, []).append(item)
        return groups

    def aggregate(
        self,
        field: str,
        func: str = "sum",
    ) -> Union[int, float, None]:
        values = [item.get(field, 0) for item in self.data]
        if not values:
            return 0 if func == "sum" else None
        if func == "sum":
            return sum(values)
        if func == "avg":
            return sum(values) / len(values)
        if func == "min":
            return min(values)
        if func == "max":
            return max(values)
        raise ValueError(f"Unknown aggregate function: {func}")

    def process(self, operation: str, **kwargs) -> Any:
        if operation == "filter":
            return self.filter(kwargs["field"], kwargs["value"])
        if operation == "sort":
            return self.sort(kwargs.get("key"), kwargs.get("reverse", False))
        if operation == "group":
            return self.group(kwargs["field"])
        if operation == "aggregate":
            return self.aggregate(kwargs["field"], kwargs.get("func", "sum"))
        raise ValueError(f"Unknown operation: {operation}")


def process(data: List[Dict[str, Any]], operation: str, extra: Optional[Dict[str, Any]] = None) -> Any:
    processor = DataProcessor(data)
    return processor.process(operation, **(extra or {}))
